from decimal import Decimal


class InsufficientFundsError(Exception):
    pass


class Account:
    def __init__(self, owner: str, balance: Decimal = Decimal("0")) -> None:
        if balance < 0:
            raise ValueError("opening balance cannot be negative")
        self.owner = owner
        self._balance = balance

    @property
    def balance(self) -> Decimal:
        return self._balance

    @classmethod
    def from_dict(cls, data: dict[str, str]) -> "Account":
        return cls(data["owner"], Decimal(data.get("balance", "0")))

    def deposit(self, amount: Decimal) -> Decimal:
        if amount <= 0:
            raise ValueError("deposit must be positive")
        self._balance += amount
        return self._balance

    def withdraw(self, amount: Decimal) -> Decimal:
        if amount <= 0:
            raise ValueError("withdrawal must be positive")
        if amount > self._balance:
            raise InsufficientFundsError(f"balance {self._balance} is less than {amount}")
        self._balance -= amount
        return self._balance
